  /// Customer who requested email verification. {@link
  /// ecommerce_mall_customers.id}.
  ecommerce_mall_customer_id String @db.Uuid

  /// Unique verification token sent to customer's email address.
  token String

  /// Expiration timestamp for the verification token.
  expires_at DateTime @db.Timestamptz

  /// IP address from which verification was requested.
  ip String?

  /// User agent string from verification request.
  user_agent String?

  /// When this verification record was created.
  created_at DateTime @db.Timestamptz

  /// When this verification record was last updated.
  updated_at DateTime @db.Timestamptz

  /// When this verification record was soft-deleted (if applicable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  customer ecommerce_mall_customers @relation(fields: [ecommerce_mall_customer_id], references: [id], onDelete: Cascade, map: "ecommerce_mall_customer_email_verifications_ecommerce__056f6df1")

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_customer_id, created_at], map: "ecommerce_mall_customer_email_verifications_ecommerce__019d1e3d")
  @@index([expires_at])
}

/// Seller accounts with email/password credentials and authentication
