  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions ecommerce_mall_seller_sessions[]
  passwordResets ecommerce_mall_seller_password_resets[]
  emailVerification ecommerce_mall_seller_email_verifications?
  shopProfile ecommerce_mall_shop_profiles?
  profileSnapshots ecommerce_mall_shop_profile_snapshots[]
  cancellationRequests ecommerce_mall_cancellation_requests[]
  refundRequests ecommerce_mall_refund_requests[]
  cancellationRequestSnapshots ecommerce_mall_cancellation_request_snapshots[]
  sellerRegistration ecommerce_mall_seller_registrations?
  suspensions ecommerce_mall_seller_suspensions[]
  orderOverrides ecommerce_mall_order_overrides[]
  orderItems ecommerce_mall_order_items[]
  shipments ecommerce_mall_shipments[]
  products ecommerce_mall_products[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@unique([shop_name])
  @@index([approval_status])
  @@index([is_suspended])
  @@index([created_at])
  @@index([updated_at])
}

