  /// Admin user's {@link ecommerce_mall_admins.id}.
  admin_id String @db.Uuid

  /// Administrator grade level (regular|super).
  grade String

  /// Timestamp when this role grade was assigned.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this role grade was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  admin ecommerce_mall_admins @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
