  /// Task name for identification and logging.
  name String

  /// Detailed description of what the task does and why it exists.
  description String?

  /// Cron expression defining the task schedule. Format: minute hour day month
  /// weekday.
  cron_expression String

  /// Timezone for cron expression evaluation (e.g., 'UTC', 'Asia/Seoul').
  timezone String?

  /// The next scheduled execution time in the configured timezone.
  next_execution_at DateTime @db.Timestamptz

  /// Maximum execution duration in seconds before timeout. Default 3600 (1
  /// hour).
  timeout_seconds Int? @db.Integer

  /// Maximum number of retry attempts on failure. Default 3.
  max_retries Int? @db.Integer

  /// Delay in seconds between retry attempts. Default 60.
  retry_delay_seconds Int? @db.Integer

  /// Policy for handling concurrent executions: 'allow', 'deny', 'wait'.
  concurrent_policy String

  /// Whether the task is currently enabled and should be executed.
  is_active Boolean

  /// Current status of the task: 'pending', 'running', 'completed', 'failed',
