  /// Parent job queue's {@link ecommerce_mall_job_queues.id}.
  job_queue_id String @db.Uuid

  /// The key name for this payload data field.
  key String

  /// The string representation of the data value. JSON objects/arrays are
  /// serialized as strings.
  value String

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Deletion timestamp (nullable for soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
