      orderId: order.id,
    },
  );
  typia.assert(page2);
  TestValidator.equals("pagination limit matches", page2.pagination.limit, 2);
  // 6. Verify data integrity
  TestValidator.equals(
    "data length",
    page1.data.length,
    page1.pagination.limit,
  );
  page1.data.forEach((item) => typia.assert(item));
}

