    adminConnection,
    {
      categoryId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        name: RandomGenerator.name(2),
        parent_category_id: parentCategory.category_id,
      } satisfies IEcommerceMallCategory.IUpdate,
