  const superFilter: IEcommerceMallAdminRole.IRequest = {
    grade: "super" as const,
  };
  const superResult =
    await api.functional.ecommerceMall.admin.admin_roles.index(
      superAdminAuthConnection,
      {
        body: superFilter,
      },
    );
