export async function test_api_seller_dashboard_statistics_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create seller with products
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
    } satisfies IEcommerceMallSeller.IJoin,
  });
  typia.assert(seller);
  // 2. Create another seller for isolation test
  const otherSellerConnection: api.IConnection = { host: connection.host };
  const otherSeller = await authorize_seller_join(otherSellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
    } satisfies IEcommerceMallSeller.IJoin,
  });
  typia.assert(otherSeller);
  // 3. Create a new seller with no products/orders for zero counts test
  const newSellerConnection: api.IConnection = { host: connection.host };
  const newSeller = await authorize_seller_join(newSellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
    } satisfies IEcommerceMallSeller.IJoin,
  });
  typia.assert(newSeller);
  // 4. Retrieve dashboard statistics for seller with products
  const dashboard =
    await api.functional.ecommerceMall.seller.analytics.dashboard.at(
      sellerConnection,
      {
        body: {},
      },
    );
  typia.assert(dashboard);
  // 5. Validate counts for seller
  TestValidator.equals("active products count", dashboard.totalProducts, 0);
  TestValidator.equals(
    "pending cancellation requests",
    dashboard.pendingCancellationRequests,
    0,
  );
  TestValidator.equals(
    "pending refund requests",
    dashboard.pendingRefundRequests,
    0,
  );
  TestValidator.equals(
    "total order items sold",
    dashboard.totalOrderItemsSold,
    0,
  );
  // 6. Verify other seller has different counts (isolated data)
  const otherDashboard =
    await api.functional.ecommerceMall.seller.analytics.dashboard.at(
      otherSellerConnection,
      {
        body: {},
      },
    );
  typia.assert(otherDashboard);
  TestValidator.equals(
    "other seller counts match empty counts",
    otherDashboard.totalProducts,
    0,
  );
  // 7. Test zero counts for seller with no products
  const emptyDashboard =
    await api.functional.ecommerceMall.seller.analytics.dashboard.at(
      newSellerConnection,
      {
        body: {},
      },
    );
  typia.assert(emptyDashboard);
  TestValidator.equals(
    "empty seller products",
    emptyDashboard.totalProducts,
    0,
  );
  TestValidator.equals(
    "empty seller orders",
    emptyDashboard.totalOrderItemsSold,
    0,
  );
  TestValidator.equals(
    "empty seller cancellations",
    emptyDashboard.pendingCancellationRequests,
    0,
  );
  TestValidator.equals(
    "empty seller refunds",
    emptyDashboard.pendingRefundRequests,
    0,
  );
}

