            variant_options: true,
            product_price: true,
            item_status: true,
            product_id: true,
            variant_id: true,
            seller_id: true,
            product: {
              select: {
                id: true,
                name: true,
                base_price: true,
                is_available: true,
                created_at: true,
                seller_id: true,
                seller: {
                  select: {
                    id: true,
                    shop_name: true,
                    approval_status: true,
                    is_suspended: true,
                    created_at: true,
                  },
                },
                images: {
                  select: {
                    id: true,
                    image_url: true,
                    sort_order: true,
                    is_main: true,
                    created_at: true,
                    updated_at: true,
                    deleted_at: true,
                  },
                } satisfies Prisma.ecommerce_mall_product_imagesFindManyArgs,
              },
            } satisfies Prisma.ecommerce_mall_productsFindManyArgs,
            variant: {
              select: {
                id: true,
                sku_code: true,
                price_override: true,
                stock_quantity: true,
              },
            } satisfies Prisma.ecommerce_mall_product_variantsFindManyArgs,
