          },
          main_image: {
            id:
              record.orderItem.product.images.find((img) => img.is_main)?.id ||
              record.orderItem.product.images[0].id,
            image_url:
              record.orderItem.product.images.find((img) => img.is_main)
                ?.image_url || record.orderItem.product.images[0].image_url,
