}): Promise<IEcommerceMallOrderOverride> {
  const orderItem =
    await MyGlobal.prisma.ecommerce_mall_order_items.findUniqueOrThrow({
      where: { id: props.body.order_item_id },
      select: { id: true, order_id: true, seller_id: true },
