export async function patchEcommerceMallProductsProductIdReviews(props: {
  productId: string;
  body: IEcommerceMallReview.IRequest;
}): Promise<IEcommerceMallReview> {
  const review = await MyGlobal.prisma.ecommerce_mall_reviews.findFirstOrThrow({
    where: {
      product_id: props.productId,
      deleted_at: null,
    },
    select: {
      id: true,
      rating: true,
      text_content: true,
      created_at: true,
      updated_at: true,
      customer_id: true,
      product_id: true,
    },
  });
  await MyGlobal.prisma.ecommerce_mall_review_snapshots.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      ecommerce_mall_review_id: review.id,
      rating: review.rating,
      text_content: review.text_content,
      snapshot_type: "edit",
      created_at: new Date(),
    },
  });
  const updated = await MyGlobal.prisma.ecommerce_mall_reviews.update({
    where: { id: review.id },
    data: {
      rating: props.body.rating,
      text_content: props.body.text_content ?? null,
      updated_at: new Date(),
    },
    select: {
      id: true,
      rating: true,
      text_content: true,
      created_at: true,
      updated_at: true,
      customer_id: true,
      product_id: true,
    },
  });
  return {
    id: updated.id as string & tags.Format<"uuid">,
    rating: updated.rating,
    text_content: updated.text_content ?? null,
    created_at: toISOStringSafe(updated.created_at) as string &
      tags.Format<"date-time">,
    review: {
      id: review.id as string & tags.Format<"uuid">,
      rating: review.rating,
      customer: {
        id: review.customer_id as string & tags.Format<"uuid">,
      } as any,
      product: { id: review.product_id as string & tags.Format<"uuid"> } as any,
      seller: null as any,
      images: [] as any,
      created_at: toISOStringSafe(review.created_at) as string &
        tags.Format<"date-time">,
      updated_at: toISOStringSafe(review.updated_at) as string &
        tags.Format<"date-time">,
    } as any,
    snapshot_type: "edit",
  };
}

import { IEcommerceMallUserBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallUserBan";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { EcommerceMallUserBanTransformer } from "../transformers/EcommerceMallUserBanTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAdminUserBans(props: {
  admin: AdminPayload;
  body: IEcommerceMallUserBan.ICreate;
}): Promise<IEcommerceMallUserBan> {
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const target = await MyGlobal.prisma.$transaction(async (tx) => {
    const [customer, seller] = await Promise.all([
      props.body.user_type === "customer"
        ? tx.ecommerce_mall_customers.findUnique({
            where: { id: props.body.user_id },
            select: { id: true, sessions: true },
          })
        : null,
      props.body.user_type === "seller"
        ? tx.ecommerce_mall_sellers.findUnique({
            where: { id: props.body.user_id },
            select: { id: true },
          })
        : null,
    ]);
    if (!customer && !seller) {
      throw new HttpException("Target user not found", 404);
    }
    const existingBan = await tx.ecommerce_mall_user_bans.findFirst({
      where: { user_id: props.body.user_id, is_active: true },
    });
    if (existingBan) {
      throw new HttpException("User is already banned", 409);
    }
    const suspendedSeller =
      await tx.ecommerce_mall_seller_suspensions.findUnique({
        where: { id: props.body.user_id },
      });
    if (suspendedSeller) {
      throw new HttpException("Seller is already suspended", 409);
    }
    const createdBan = await tx.ecommerce_mall_user_bans.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        user_id: props.body.user_id,
        admin_id: props.admin.id,
        seller_registration_id:
          props.body.user_type === "seller" ? undefined : null,
        user_type: props.body.user_type,
        reason: props.body.reason,
        banned_at: now,
        unban_at: props.body.unban_at ?? null,
        is_active: true,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
      select: EcommerceMallUserBanTransformer.select().select,
    });
    if (props.body.user_type === "customer" && customer) {
      await tx.ecommerce_mall_customer_sessions.updateMany({
        where: { customer: { id: props.body.user_id } },
        data: {},
      });
    }
    if (props.body.user_type === "seller" && seller) {
      await tx.ecommerce_mall_seller_sessions.updateMany({
        where: { seller: { id: props.body.user_id } },
        data: {},
      });
    }
    return createdBan;
  });
  return await EcommerceMallUserBanTransformer.transform(target);
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEcommerceMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomer";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAuthCustomerLogin(props: {
  ip: string;
  body: IEcommerceMallCustomer.ILogin;
}): Promise<IEcommerceMallCustomer.IAuthorized> {
  // 1. Find customer with password_hash
  const customer = await MyGlobal.prisma.ecommerce_mall_customers.findFirst({
    where: { email: props.body.email, deleted_at: null },
    select: {
      id: true,
      email: true,
      password_hash: true,
      created_at: true,
    },
  });
  if (!customer) throw new HttpException("Invalid credentials", 401);
  // 2. Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    customer.password_hash,
  );
  if (!isValid) throw new HttpException("Invalid credentials", 401);
  // 3. Create NEW session
  const accessExpires = new Date(Date.now() + 15 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const customerId = customer.id as string & tags.Format<"uuid">;
  const sessionId = v4() as string & tags.Format<"uuid">;
  const session = await MyGlobal.prisma.ecommerce_mall_customer_sessions.create(
    {
      data: {
        id: sessionId,
        customer: { connect: { id: customerId } },
        ip: props.body.ip ?? props.ip,
        href: props.body.href,
        referrer: props.body.referrer,
        access_token: jwt.sign(
          {
            type: "customer" as string,
            id: customerId,
            session_id: sessionId,
            created_at: toISOStringSafe(new Date()),
          },
          MyGlobal.env.JWT_SECRET_KEY,
          {
            expiresIn: "15m",
            issuer: "autobe",
          },
        ),
        refresh_token: jwt.sign(
          {
            type: "customer" as string,
            id: customerId,
            session_id: sessionId,
            created_at: toISOStringSafe(new Date()),
            tokenType: "refresh" as string,
          },
          MyGlobal.env.JWT_SECRET_KEY,
          {
            expiresIn: "7d",
            issuer: "autobe",
          },
        ),
        expires_at: toISOStringSafe(accessExpires),
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
      select: {
        id: true,
        customer: true,
        access_token: true,
        refresh_token: true,
        expires_at: true,
        created_at: true,
        updated_at: true,
      },
    },
  );
  // 4. Build response
  return {
    access_token: session.access_token,
    refresh_token: session.refresh_token,
    expired_at: toISOStringSafe(session.expires_at),
    customer: {
      id: customer.id,
      email: customer.email,
      is_suspended: false,
      created_at: toISOStringSafe(customer.created_at),
    },
    token: {
      access: session.access_token,
      refresh: session.refresh_token,
      expired_at: toISOStringSafe(session.expires_at),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  } satisfies IEcommerceMallCustomer.IAuthorized;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEcommerceMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallSeller";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAuthSellerLogin(props: {
  ip: string;
  body: IEcommerceMallSeller.ILogin;
}): Promise<IEcommerceMallSeller.IAuthorized> {
  const seller = await MyGlobal.prisma.ecommerce_mall_sellers.findFirst({
    where: { email: props.body.email },
    select: {
      id: true,
      email: true,
      shop_name: true,
      shop_description: true,
      logo_url: true,
      approval_status: true,
      is_suspended: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      password_hash: true,
    },
  });
  if (!seller) throw new HttpException("Invalid credentials", 401);
  const isValid = await PasswordUtil.verify(
    props.body.password,
    seller.password_hash,
  );
  if (!isValid) throw new HttpException("Invalid credentials", 401);
  if (seller.deleted_at !== null)
    throw new HttpException("Account is deleted", 403);
  if (seller.is_suspended) throw new HttpException("Account is suspended", 403);
  if (seller.approval_status !== "approved")
    throw new HttpException("Account is not approved", 403);
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.ecommerce_mall_seller_sessions.create({
    data: {
      id: v4(),
      ecommerce_mall_seller_id: seller.id,
      ip: props.ip,
      created_at: toISOStringSafe(new Date()),
      expired_at: toISOStringSafe(accessExpires),
      access_token: "",
      refresh_token: "",
      user_agent: "",
      referrer: "",
      is_revoked: false,
    },
  });
  const token = {
    access: jwt.sign(
      {
        type: "seller",
        id: seller.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "seller",
        id: seller.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  const response = {
    id: seller.id as string & tags.Format<"uuid">,
    email: seller.email,
    shop_name: seller.shop_name,
    shop_description: seller.shop_description ?? undefined,
    logo_url: seller.logo_url ?? undefined,
    approval_status: seller.approval_status,
    is_suspended: seller.is_suspended,
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    deleted_at: seller.deleted_at ? toISOStringSafe(seller.deleted_at) : null,
    access: token.access,
    refresh: token.refresh,
    expired_at: token.expired_at,
    token: {
      access: token.access,
      refresh: token.refresh,
      expired_at: token.expired_at,
      refreshable_until: token.refreshable_until,
    } satisfies IAuthorizationToken,
  } satisfies IEcommerceMallSeller.IAuthorized;
  return response;
}

import { IEcommerceMallCustomerBehavior } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomerBehavior";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIEcommerceMallCustomerBehavior } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMallCustomerBehavior";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchEcommerceMallSellerAnalyticsCustomerBehavior(props: {
  seller: SellerPayload;
  body: IEcommerceMallCustomerBehavior.IRequest;
}): Promise<IPageIEcommerceMallCustomerBehavior.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  // Build where conditions for orders
  const whereConditions: Prisma.ecommerce_mall_ordersWhereInput = {
    customer: {
      deleted_at: null,
    },
    orderItems: {
      some: {
        seller_id: props.seller.id,
      },
    },
    deleted_at: null,
  };
  // Date range filtering
  if (props.body.start_date || props.body.end_date) {
    if (props.body.start_date) {
      whereConditions.created_at = whereConditions.created_at || {};
      whereConditions.created_at = {
        ...(whereConditions.created_at as any),
        gte: toISOStringSafe(props.body.start_date),
      };
    }
    if (props.body.end_date) {
      whereConditions.created_at = whereConditions.created_at || {};
      whereConditions.created_at = {
        ...(whereConditions.created_at as any),
        lte: toISOStringSafe(props.body.end_date),
      };
    }
  }
  // Get total count
  const total = await MyGlobal.prisma.ecommerce_mall_orders.count({
    where: whereConditions,
  });
  // Get paginated orders with related data
  const orders = await MyGlobal.prisma.ecommerce_mall_orders.findMany({
    where: whereConditions,
    skip,
    take: limit,
    orderBy: props.body.sort_by
      ? {
          created_at: props.body.sort_order === "asc" ? "asc" : "desc",
        }
      : { created_at: "desc" },
    include: {
      orderItems: {
        where: {
          seller_id: props.seller.id,
        },
        include: {
          product: {
            include: {
              category: true,
            },
          },
        },
      },
    },
  });
  // Calculate aggregated metrics per product
  const productMetrics: Record<
    string,
    {
      product_id: string & tags.Format<"uuid">;
      product_name: string;
      product_category: string;
      view_count: number & tags.Type<"int32"> & tags.Minimum<0>;
      cart_add_count: number & tags.Type<"int32"> & tags.Minimum<0>;
      purchase_count: number & tags.Type<"int32"> & tags.Minimum<0>;
      conversion_rate: number & tags.Minimum<0> & tags.Maximum<100>;
      average_order_value: number & tags.Minimum<0>;
      total_revenue: number & tags.Minimum<0>;
      cart_abandonment_rate: number & tags.Minimum<0> & tags.Maximum<100>;
      time_period: string;
    }
  > = {};
  // Process orders to aggregate metrics
  for (const order of orders) {
    const orderDate = order.created_at;
    for (const item of order.orderItems) {
      if (!productMetrics[item.product.id]) {
        productMetrics[item.product.id] = {
          product_id: item.product.id as string & tags.Format<"uuid">,
          product_name: item.product_name,
          product_category: item.product.category?.name ?? "",
          view_count: 0,
          cart_add_count: 0,
          purchase_count: 0,
          conversion_rate: 0,
          average_order_value: 0,
          total_revenue: 0,
          cart_abandonment_rate: 0,
          time_period: "30d",
        };
      }
      // Increment purchase count and revenue
      productMetrics[item.product.id].purchase_count++;
      productMetrics[item.product.id].total_revenue += Number(
        item.product_price,
      );
    }
  }
  // Calculate derived metrics and build summary data
  const summaryData: IEcommerceMallCustomerBehavior.ISummary[] = Object.values(
    productMetrics,
  ).map((metric) => ({
    ...metric,
    conversion_rate:
      metric.purchase_count > 0 && metric.view_count > 0
        ? (Number(
            ((metric.purchase_count / metric.view_count) * 100).toFixed(2),
          ) as number & tags.Minimum<0> & tags.Maximum<100>)
        : 0,
    average_order_value:
      metric.purchase_count > 0
        ? (Number(
            (metric.total_revenue / metric.purchase_count).toFixed(2),
          ) as number & tags.Minimum<0>)
        : 0,
  }));
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: summaryData,
  };
}

import { IEcommerceMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallProductImage";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIEcommerceMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMallProductImage";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { EcommerceMallProductImageTransformer } from "../transformers/EcommerceMallProductImageTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchEcommerceMallSellerProductsProductIdImages(props: {
  seller: SellerPayload;
  productId: string;
  body: IEcommerceMallProductImage.IRequest;
}): Promise<IPageIEcommerceMallProductImage.ISummary> {
  // Verify seller owns the product
  const product =
    await MyGlobal.prisma.ecommerce_mall_products.findUniqueOrThrow({
      where: { id: props.productId as string & tags.Format<"uuid"> },
      select: { seller_id: true },
    });
  if (product.seller_id !== props.seller.id) {
    throw new HttpException("Forbidden", 403);
  }
  // Query existing images for the product
  const existingImages =
    await MyGlobal.prisma.ecommerce_mall_product_images.findMany({
      where: {
        product_id: props.productId as string & tags.Format<"uuid">,
        deleted_at: null,
      },
      orderBy: { sort_order: "asc" },
      ...EcommerceMallProductImageTransformer.select(),
    });
  // Process reorder instructions
  const sortOrderMap = new Map<string, number>();
  const existingImageMap = new Map<string, any>();
  for (const img of existingImages) {
    existingImageMap.set(img.id, img);
  }
  // Validate all reorder instructions
  const body = typia.assert<IEcommerceMallProductImage.IRequest[]>(props.body);
  for (const reorder of body) {
    const existing = existingImageMap.get(reorder.id);
    if (!existing) {
      throw new HttpException(`Image with ID ${reorder.id} not found`, 404);
    }
    if (sortOrderMap.has(String(reorder.sort_order))) {
      throw new HttpException(
        `Duplicate sort_order value ${String(reorder.sort_order)}`,
        400,
      );
    }
    sortOrderMap.set(String(reorder.sort_order), existing.id as number);
  }
  // Update sort_order for each image
  const updates = body.map((reorder) =>
    MyGlobal.prisma.ecommerce_mall_product_images.update({
      where: { id: reorder.id as string & tags.Format<"uuid"> },
      data: {
        sort_order: reorder.sort_order,
        updated_at: toISOStringSafe(new Date()),
      },
    }),
  );
  await Promise.all(updates);
  // Retrieve updated images with proper fields
  const updatedImages =
    await MyGlobal.prisma.ecommerce_mall_product_images.findMany({
      where: {
        product_id: props.productId as string & tags.Format<"uuid">,
        deleted_at: null,
      },
      orderBy: { sort_order: "asc" },
      ...EcommerceMallProductImageTransformer.select(),
    });
  const limit = 100;
  const page = 1;
  const startIndex = (page - 1) * limit;
  const paginatedData = updatedImages.slice(startIndex, startIndex + limit);
  const result = await ArrayUtil.asyncMap(
    paginatedData,
    EcommerceMallProductImageTransformer.transform,
  );
  return {
    data: result,
    pagination: {
      current: page,
      limit: limit,
      records: updatedImages.length,
      pages: Math.ceil(updatedImages.length / limit),
    } satisfies IPage.IPagination,
  };
}

import { IEcommerceMallRateLimitTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallRateLimitTracking";
