export async function patchEcommerceMallSellerOrdersOrderIdItemsOrderItemIdRefundApprove(props: {
  seller: SellerPayload;
  orderId: string;
  orderItemId: string;
}): Promise<IEcommerceMallRefundRequest> {
  const refundRequest =
    await MyGlobal.prisma.ecommerce_mall_refund_requests.findUniqueOrThrow({
      where: { id: props.orderItemId },
      select: {
        id: true,
        order_item_id: true,
        customer_id: true,
        seller_id: true,
        reason: true,
        status: true,
        responded_at: true,
        created_at: true,
        updated_at: true,
      },
    });
  if (refundRequest.status !== "pending") {
    throw new HttpException("Refund request is not in pending status", 400);
  }
  if (refundRequest.seller_id !== props.seller.id) {
    throw new HttpException("Forbidden", 403);
  }
  const orderItem =
    await MyGlobal.prisma.ecommerce_mall_order_items.findUniqueOrThrow({
      where: { id: props.orderItemId },
      select: { id: true, item_status: true, variant_id: true },
    });
  if (orderItem.item_status !== "delivered") {
    throw new HttpException(
      "Refund can only be requested for delivered items",
      400,
    );
  }
  const now = new Date();
  const updatedRefundRequest = await MyGlobal.prisma.$transaction(
    async (prisma) => {
      const updated = await prisma.ecommerce_mall_refund_requests.update({
        where: { id: refundRequest.id },
        data: {
          status: "approved",
          responded_at: now,
        },
      });
      await prisma.ecommerce_mall_refund_request_snapshots.create({
        data: {
          id: v4(),
          refund_request_id: refundRequest.id,
          reason: refundRequest.reason,
          status: refundRequest.status,
          created_at: refundRequest.created_at,
          updated_at: refundRequest.updated_at,
          snapshot_type: "refund_approved",
        },
      });
      await prisma.ecommerce_mall_inventory_records.create({
        data: {
          id: v4(),
          variant_id: orderItem.variant_id,
          quantity_change: 1,
          reason: "refund",
          reference_id: refundRequest.id,
          created_at: now,
        },
      });
      await prisma.ecommerce_mall_order_items.update({
        where: { id: props.orderItemId },
        data: {
          item_status: "refunded",
          updated_at: now,
        },
      });
      const orderItems = await prisma.ecommerce_mall_order_items.findMany({
        where: { order_id: props.orderId },
        select: { item_status: true },
      });
      const allRefunded = orderItems.every(
        (item) => item.item_status === "refunded",
      );
      if (allRefunded) {
        await prisma.ecommerce_mall_orders.update({
          where: { id: props.orderId },
          data: {
            order_status: "refunded",
            updated_at: now,
          },
        });
      }
      return updated;
    },
  );
  const fullRecord =
    await MyGlobal.prisma.ecommerce_mall_refund_requests.findUniqueOrThrow({
      where: { id: updatedRefundRequest.id },
      ...EcommerceMallRefundRequestTransformer.select(),
    });
  return await EcommerceMallRefundRequestTransformer.transform(fullRecord);
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEcommerceMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomer";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAuthCustomerRefresh(props: {
  body: IEcommerceMallCustomer.IRefresh;
}): Promise<IEcommerceMallCustomer.IAuthorized> {
  // 1. Verify refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "customer";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as typeof decoded;
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  // 2. Validate token type
  if (decoded.type !== "customer") {
    throw new HttpException("Invalid token type", 401);
  }
  // 3. Validate session exists and not expired
  const session =
    await MyGlobal.prisma.ecommerce_mall_customer_sessions.findFirst({
      where: {
        id: decoded.session_id,
        ecommerce_mall_customer_id: decoded.id,
        expires_at: { gte: new Date() },
      },
    });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  // 4. Validate customer account exists and is not deleted
  const customer =
    await MyGlobal.prisma.ecommerce_mall_customers.findUniqueOrThrow({
      where: { id: decoded.id },
    });
  if (customer.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }
  // 5. Generate new tokens
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const newAccessToken = jwt.sign(
    {
      type: "customer",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const newRefreshToken = jwt.sign(
    {
      type: "customer",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  // 6. Update session expiration
  await MyGlobal.prisma.ecommerce_mall_customer_sessions.update({
    where: { id: decoded.session_id },
    data: {
      access_token: newAccessToken,
      refresh_token: newRefreshToken,
      expires_at: accessExpires,
    },
  });
  // 7. Build response with customer summary
  const customerSummary: IEcommerceMallCustomer.ISummary = {
    id: customer.id as string & tags.Format<"uuid">,
    email: customer.email as string & tags.Format<"email">,
    is_suspended: false,
    created_at: customer.created_at.toISOString() as string &
      tags.Format<"date-time">,
  };
  return {
    access_token: newAccessToken,
    refresh_token: newRefreshToken,
    expired_at: accessExpires.toISOString() as string &
      tags.Format<"date-time">,
    customer: customerSummary,
    token: {
      access: newAccessToken,
      refresh: newRefreshToken,
      expired_at: accessExpires.toISOString() as string &
        tags.Format<"date-time">,
      refreshable_until: refreshExpires.toISOString() as string &
        tags.Format<"date-time">,
    },
  };
}

