    });
  const total =
    await MyGlobal.prisma.ecommerce_mall_shop_profile_snapshots.count({
      where: whereInput,
    });
  return {
    data: await ArrayUtil.asyncMap(
      data,
      EcommerceMallShopProfileAtSummaryTransformer.transform,
    ),
    pagination: {
      current: page,
