  body: IEcommerceMallShipment.IUpdate;
}): Promise<void> {
  // Find shipment by ID
  const shipment =
    await MyGlobal.prisma.ecommerce_mall_shipments.findUniqueOrThrow({
      where: { id: props.shipmentId },
      select: { ecommerce_mall_seller_id: true },
