import { patchEcommerceMallSellerOrdersOrderIdItemsOrderItemIdCancelReject } from "../../../../../../../providers/patchEcommerceMallSellerOrdersOrderIdItemsOrderItemIdCancelReject";

@Controller(
  "/ecommerceMall/seller/orders/:orderId/items/:orderItemId/cancel/reject",
)
export class EcommercemallSellerOrdersItemsCancelController {
  /**
   * Reject a customer's cancellation request for an order item.
   *
   * This endpoint allows sellers to formally reject a pending cancellation request submitted by a customer. Rejection preserves the order item's current status and does not modify the order or inventory.
   *
   * When a seller rejects a cancellation request, the system:
   * - Changes the cancellation request status to 'rejected'
   * - Records the rejection timestamp in responded_at
   * - Stores the rejection reason for audit trail
   * - Does NOT restore inventory (since cancellation did not occur)
   * - Does NOT modify the order or shipment status
   *
   * Only sellers can reject cancellation requests, and only for items belonging to their own shop. The system enforces strict ownership validation to prevent unauthorized rejections.
   *
   * For rejection to be valid, the order item must be in an eligible status (typically 'paid' for pre-shipment cancellations) and the cancellation request must still be in 'pending' status. Attempting to reject an already-approved, already-rejected, or ineligible item will result in an error response.
   *
   * Related operations:
   * - Customers submit cancellation requests via PATCH /orders/{orderId}/items/{orderItemId}/cancel
   * - Sellers approve cancellation requests via PATCH /orders/{orderId}/items/{orderItemId}/cancel/approve
   * - Admins can override and cancel orders via admin endpoints
   *
   * Security Note: This operation is only available to authenticated sellers. Sellers can only reject requests for order items belonging to their own shop account.
   *
   * @param connection
   * @param orderId Order identifier in UUID format
   * @param orderItemId Order item identifier in UUID format
   * @param body Rejection reason from seller
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Query the ecommerce_mall_cancellation_requests table for a pending request linked to the provided orderItemId. Verify the cancellation request's status is 'pending' and its orderItemId matches the path parameter. Verify the order item belongs to the seller's shop via the seller_id foreign key. Validate the order item status is eligible for cancellation (typically 'paid' for pre-shipment requests). If the cancellation request does not exist, status is not 'pending', order item belongs to another seller, or item status is ineligible, return an appropriate error. Update the cancellation request status to 'rejected', set responded_at to current timestamp, and store rejection reason from request body. Create a cancellation_request_snapshot record to preserve the state at rejection time for audit and dispute resolution. Ensure all operations occur within a single database transaction to maintain consistency. Return the updated cancellation request object with all fields.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async reject(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("orderId")
    orderId: string,
    @TypedParam("orderItemId")
    orderItemId: string,
    @TypedBody()
    body: IEcommerceMallCancellationRequest.IUpdate,
  ): Promise<IEcommerceMallCancellationRequest> {
    try {
      return await patchEcommerceMallSellerOrdersOrderIdItemsOrderItemIdCancelReject(
        {
          seller,
          orderId,
          orderItemId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

